import{_ as r,o as n,c as t,a6 as a}from"./chunks/framework.DNkVJs23.js";const c=JSON.parse('{"title":"Über Sapphire Star Codex","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/de/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/de/others/"}],["meta",{"property":"og:title","content":"Über Sapphire Star Codex | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster-Hunter-Daten und Rüstungssuche für Wilds, Rise mit Sunbreak und World mit Iceborne."}]]},"headers":[],"relativePath":"de/others/index.md","filePath":"de/others/index.md"}'),i={name:"de/others/index.md"};function o(d,e,l,s,u,h){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="uber-sapphire-star-codex" tabindex="-1">Über Sapphire Star Codex <a class="header-anchor" href="#uber-sapphire-star-codex" aria-label="Permalink to &quot;Über Sapphire Star Codex&quot;">​</a></h1><h2 id="das-projekt" tabindex="-1">Das Projekt <a class="header-anchor" href="#das-projekt" aria-label="Permalink to &quot;Das Projekt&quot;">​</a></h2><p>Sapphire Star Codex verbindet Monster-Hunter-Daten mit einer Rüstungssuche. Die App wird unabhängig vom Entwickler von <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a> gepflegt und ist kostenlos, ohne Werbung oder kostenpflichtige Funktionen.</p><p>Android ist bei <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a>, HarmonyOS in der <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a> verfügbar. iOS wird für die Veröffentlichung vorbereitet. Unter <a href="./../#download">Download</a> findest du die aktuellen Links. Die Verfügbarkeit hängt von Region und Gerät ab.</p><h2 id="ruckmeldungen-und-unterstutzung" tabindex="-1">Rückmeldungen und Unterstützung <a class="header-anchor" href="#ruckmeldungen-und-unterstutzung" aria-label="Permalink to &quot;Rückmeldungen und Unterstützung&quot;">​</a></h2><p>Nenne bei Fehlermeldungen Spiel, Eintrag, Sprache, Schritte und eine überprüfbare Quelle. Verdecke persönliche Angaben in Screenshots. Kontakt: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Auch Weiterempfehlungen, Korrekturen und <a href="./../support/">freiwillige Unterstützung</a> helfen.</p><h2 id="quellen-und-rechte" tabindex="-1">Quellen und Rechte <a class="header-anchor" href="#quellen-und-rechte" aria-label="Permalink to &quot;Quellen und Rechte&quot;">​</a></h2><p>Die Daten stammen unter anderem aus <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>, <a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> und Spieldateien und werden mit Community-Quellen abgeglichen. Fehler und Lücken sind möglich. Namen, Grafiken und Spieldaten von Monster Hunter gehören CAPCOM; berechtigten Entfernungsaufforderungen wird nachgekommen. Die MIT-Lizenz für angepassten Pocket-Gallery-Code umfasst keine Spielgrafiken oder Spieldaten.</p>',8)])])}const f=r(i,[["render",o]]);export{c as __pageData,f as default};
